1", "                    node = {k: \"for_in\", names: fnames_k, lnames: fnames_l, coll: coll, body: fibody, block_stmt: TRUE, line: ftok[line], col: ftok[col]}", "                    block_stmt = TRUE", "                else:", "                    if len(nts) != 1:", "                        fail(st, nts[1], \"SYNTAX_ERROR\", \"one loop variable for a numeric range\", \"two variables\")", "                        return stmts", "                    dict rnt = nts[0]", "                    str rname = rnt[value]", "                    if is_const_name(rname):", "                        fail(st, rnt, \"CONST_ERROR\", \"variable\", cat([\"constant '\", rname, \"'\"]))", "                        return stmts", "                    if is_reserved(rname):", "                        fail(st, rnt, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", rname, \"'\"]))", "                        return stmts", "                    dict rvars = st[vars]", "                    dict rfor = st[for_names]", "                    dict rgv = st[gvars]", "                    if rvars.contains(rname) OR rfor.contains(rname) OR rgv.contains(rname):", "                        fail(st, rnt, \"REDECLARE_ERROR\", \"unique loop variable\", cat([\"name '\", rname, \"' is already declared\"]))", "                        return stmts", "                    rvars.add(rname, \"flint\")", "                    rfor.add(rname, TRUE)", "                    str rlua = mangle_var(st, rname)", "                    dict first = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    dict ftnode = {k: \"for\", name: rname, lua: rlua, line: ftok[line], col: ftok[col]}", "                    if first[k] == \"range\":", "                        ftnode.add(\"form\", \"range\")", "                        if first[kind] == \"float\":", "                            ftnode.add(\"float_fmt\", TRUE)", "                        ftnode.add(\"from