                str mname = mnt[value]", "                if is_reserved(mname) OR is_const_name(mname):", "                    fail(st, mnt, \"NAME_ERROR\", \"free model name\", cat([\"reserved '\", mname, \"'\"]))", "                    return stmts", "                dict mall = st[models]", "                dict mgv = st[vars]", "                dict mfnc = st[funcs]", "                if mall.contains(mname) OR mgv.contains(mname) OR mfnc.contains(mname):", "                    fail(st, mnt, \"REDECLARE_ERROR\", \"unique model name\", cat([\"name '\", mname, \"' is already declared\"]))", "                    return stmts", "                dict mschema = {name: mname, model_fields: {}, field_types: {}, consts: {}, init_fields: {}, params: [], param_types: {}, methods: {}, method_order: [], ctor: NONE, order: [], field_order: []}", "                mall.add(mname, mschema)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                expect_tok(st, \"newline\", \"\", \"end of line after ':'\")", "                expect_tok(st, \"indent\", \"\", \"indented block\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                list mfield_nodes = []", "                bool mseen_construct = FALSE", "                bool mseen_method = FALSE", "                bool mgoing = TRUE", "                while mgoing:", "                    dict mbt = tk(st)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    if mbt[type] == \"dedent\" OR mbt[type] == \"eof\":", "                        mgoing = FALSE", "                    elif mbt[type] == \"newline\":", "                        advance(st)", "                    elif mbt[type] == \"kw\" AND mbt[value] == \"construct\":", "                        if mseen_construct:", "                            fail(st, mbt, \"REDECLARE_ERROR\", \"one construct per model\", \"second construct\")", "                        