st mp = [mrecv]", "        flint mi = 0", "        while mi < len(mar):", "            dict ma = mar[mi]", "            str mspec = e[a1]", "            if mi == 1:", "                mspec = e[a2]", "            str mxx = emit_expr(st, ma)", "            if mspec == \"str\":", "                mxx = wrap_str(mxx, ma[t], e_nullable(ma))", "            elif mspec == \"flint\":", "                mxx = wrap_flint(mxx, ma[t], e_nullable(ma))", "            elif mspec == \"dict\":", "                mxx = wrap_dict(mxx, ma[t], e_nullable(ma))", "            mp.add(mxx)", "            mi += 1", "        return cat([\"krt.\", e[rt], \"(\", mp.join(\", \"), \")\"])", "", "    if k == \"un\":", "        dict ua = e[a]", "        if e[op] == \"-\":", "            return cat([\"(-(\", wrap_flint(emit_expr(st, ua), ua[t], e_nullable(ua)), \"))\"])", "        return cat([\"(not krt.truthy_strict(\", emit_expr(st, ua), \"))\"])", "", "    if k == \"is\":", "        dict ia = e[a]", "        str ix2 = emit_expr(st, ia)", "        str ty2 = e[typename]", "        if ty2 == \"flint\":", "            return cat([\"(type(\", ix2, \") == \\\"number\\\")\"])", "        if ty2 == \"str\":", "            return cat([\"(type(\", ix2, \") == \\\"string\\\")\"])", "        if ty2 == \"bool\":", "            return cat([\"(type(\", ix2, \") == \\\"boolean\\\")\"])", "        str tyb = base_type(ty2)", "        if tyb == \"list\":", "            return cat([\"krt.is_list(\", ix2, \")\"])", "        if tyb == \"froz\":", "            return cat([\"krt.is_froz(\", ix2, \")\"])", "        if tyb == \"dict\":", "            return cat([\"krt.is_dict(\", ix2, \")\"])", "        if is_model_type(st, ty2):", "            return cat([\"krt.is_model(\", ix2, \", \", lua_str(ty2), \")\"])", "        return cat([\"(\", ix2, \" == krt.NONE or \", ix2, \" == nil)\"])", "", "    if k == \"range\":", "        dict rex = e[from]", "        dict rey = e[to]", "        dict rez = e[step]", "        return cat([\"krt.range_new(\", wrap_flint(emit_expr(st, rex), rex[t], e_nullable(rex)), \", \", wrap_flint(emit_expr(st, rey), rey[t], e_nullable(rey)), \", \", wrap_flint(emit_expr(st, rez), rez[t], e_nullable(rez)), \", \", lua_str(e[kind]), \")\"])", "", "    if k == \"in\":", "        dict iax = e[a]", "        dict ibx = e[b]", "        str ixf = emit_expr(st, iax)", "        str iyb = emit_expr(st, ibx)", "        if ibx[t] == \"range\":", "            return cat([\"krt.in_range(\", wrap_flint(ixf, iax[t], e_nullable(iax)), \", \", iyb, \")\"])", "        str ibt = base_type(ibx[t])", "        if ibt == \"list\" OR ibt == \"froz\":", "            return cat([\"krt.in_list(\", ixf, \", \", wrap_list(iyb, ibx[t], e_nullable(ibx)), \")\"])", "        if ibt == \"dict\":", "            return cat([\"krt.in_dict_keys(\", wrap_str(ixf, iax[t], e_nullable(iax)), \", \", wrap_dict(iyb, ibx[t], e_nullable(ibx)), \")\"])", "        if ibx[t] == \"str\":", "            return cat([\"krt.in_str(\", wrap_str(ixf, iax[t], e_nullable(iax)), \", \", wrap_str(iyb, ibx[t], e_nullable(ibx)), \")\"])", "        return cat([\"krt.in_list(\", ixf, \", \", iyb, \")\"])", "", "    if k == \"bin\":", "        str op = e[op]", "        dict bna = e[a]", "        dict bnb = e[b]", "        str xa = emit_expr(st, bna)", "        str xb = emit_expr(st, bnb)", "        if op == \"+\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" + \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"-\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" - \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"*\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" * \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"/\":", "            return cat([\"krt.div(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"//\":", "            return cat([\"krt.idiv(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"%\":", "            return cat([\"krt.mod(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"**\":", "            return cat([\"krt.pow(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"==\":", "            return cat([\"(\", xa, \" == \", xb, \")\"])", "        if op == \"!=\":", "            return cat([\"(\", xa, \" ~= \", xb, \")\"])", "        if op == \"<\" OR op == \"<=\" OR op == \">\" OR op == \">=\":", "            if bna[t] == \"any\" OR bnb[t] == \"any\":", "                str cfn = \"lt\"", "                if op == \"<=\":", "                    cfn = \"le\"", "                elif op == \">\":", "                    cfn = \"gt\"", "                elif op == \">=\":", "                    cfn = \"ge\"", "                return cat([\"krt.\", cfn, \"(\", xa, \", \", xb, \")\"])", "            return cat([\"(\", ordered_x(xa, bna, bnb), \" \", op, \" \", ordered_x(xb, bnb, bna), \")\"])", "        if op == \"AND\":", "            return cat([\"(krt.truthy_strict(\", xa, \") and krt.truthy_strict(\", xb, \"))\"])", "        if op == \"OR\":", "            return cat([\"(krt.truthy_strict(\", xa, \") or krt.truthy_strict(\", xb, \"))\"])", "        return \"krt.NONE\"", "", "    if k == \"chain\":", "        list cops = e[ops]", "        list coper = e[operands]", "        list clines = []", "        list cconds = []", "        dict cprev_node = coper[0]", "        str cprev = emit_expr(st, cprev_node)", "        flint cj = 0", "        while cj < len(cops):", "            dict co = cops[cj]", "            dict crhs_node = coper[cj + 1]", "            str crhs = \"\"", "            if cj < len(cops) - 1:", "                crhs = 